1	package server
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"io"
7		"math"
8		"net/http"
9		"sort"
10		"strconv"
11		"strings"
12	)
13	
14	// Error codes reported by the configuration validator.
15	const (
16		codeInvalidJSON             = "invalid_json"
17		codeInvalidDocument         = "invalid_document"
18		codeDuplicateIdentifier     = "duplicate_identifier"
19		codeUnknownResourceType     = "unknown_resource_type"
20		codeTypeMismatch            = "type_mismatch"
21		codeMissingRequiredProperty = "missing_required_property"
22		codeUnexpectedProperty      = "unexpected_property"
23	)
24	
25	// validationError is one machine-readable finding. Path is an RFC 6901 JSON
26	// Pointer into the submitted document.
27	type validationError struct {
28		Code    string `json:"code"`
29		Message string `json:"message"`
30		Path    string `json:"path"`
31	}
32	
33	type validateResponse struct {
34		Valid  bool              `json:"valid"`
35		Errors []validationError `json:"errors"`
36	}
37	
38	// handleValidateConfiguration validates a configuration document without
39	// creating or persisting anything.
40	func handleValidateConfiguration(w http.ResponseWriter, r *http.Request) {
41		w.Header().Set("Content-Type", "application/json; charset=utf-8")
42		if r.Method != http.MethodPost {
43			w.Header().Set("Allow", http.MethodPost)
44			w.WriteHeader(http.StatusMethodNotAllowed)
45			_ = json.NewEncoder(w).Encode(map[string]any{
46				"error": map[string]string{"code": "method_not_allowed"},
47			})
48			return
49		}
50	
51		dec := json.NewDecoder(r.Body)
52		dec.UseNumber()
53		var doc any
54		if err := dec.Decode(&doc); err != nil {
55			writeValidation(w, http.StatusBadRequest, []validationError{{
56				Code:    codeInvalidJSON,
57				Message: "request body is empty or is not valid JSON",
58				Path:    "",
59			}})
60			return
61		}
62		var trailing any
63		if err := dec.Decode(&trailing); err != io.EOF {
64			writeValidation(w, http.StatusBadRequest, []validationError{{
65				Code:    codeInvalidJSON,
66				Message: "request body must contain exactly one JSON value",
67				Path:    "",
68			}})
69			return
70		}
71	
72		errs := validateConfiguration(doc)
73		sort.SliceStable(errs, func(i, j int) bool {
74			if errs[i].Path != errs[j].Path {
75				return errs[i].Path < errs[j].Path
76			}
77			return errs[i].Code < errs[j].Code
78		})
79		if len(errs) == 0 {
80			writeValidation(w, http.StatusOK, nil)
81			return
82		}
83		writeValidation(w, http.StatusUnprocessableEntity, errs)
84	}
85	
86	func writeValidation(w http.ResponseWriter, status int, errs []validationError) {
87		if errs == nil {
88			errs = []validationError{}
89		}
90		w.WriteHeader(status)
91		_ = json.NewEncoder(w).Encode(validateResponse{Valid: len(errs) == 0, Errors: errs})
92	}
93	
94	// pointerEscape escapes a single JSON Pointer path segment per RFC 6901.
95	func pointerEscape(s string) string {
96		s = strings.ReplaceAll(s, "~", "~0")
97		return strings.ReplaceAll(s, "/", "~1")
98	}
99	
100	// validateConfiguration checks a decoded document and returns every
101	// independently determinable problem, in discovery order.
102	func validateConfiguration(doc any) []validationError {
103		var errs []validationError
104		add := func(code, message, path string) {
105			errs = append(errs, validationError{Code: code, Message: message, Path: path})
106		}
107	
108		root, ok := doc.(map[string]any)
109		if !ok {
110			add(codeInvalidDocument, "document must be a JSON object", "")
111			return errs
112		}
113		for key := range root {
114			if key != "resourceTypes" && key != "resources" {
115				add(codeInvalidDocument, fmt.Sprintf("unknown field %q", key), "/"+pointerEscape(key))
116			}
117		}
118	
119		typesRaw, hasTypes := root["resourceTypes"]
120		if !hasTypes {
121			add(codeInvalidDocument, `missing required field "resourceTypes"`, "")
122		}
123		resourcesRaw, hasResources := root["resources"]
124		if !hasResources {
125			add(codeInvalidDocument, `missing required field "resources"`, "")
126		}
127	
128		var typeEntries []any
129		if hasTypes {
130			arr, ok := typesRaw.([]any)
131			if !ok {
132				add(codeInvalidDocument, `"resourceTypes" must be an array`, "/resourceTypes")
133			} else {
134				typeEntries = arr
135			}
136		}
137		var resourceEntries []any
138		if hasResources {
139			arr, ok := resourcesRaw.([]any)
140			if !ok {
141				add(codeInvalidDocument, `"resources" must be an array`, "/resources")
142			} else {
143				resourceEntries = arr
144			}
145		}
146	
147		// declared holds every non-empty type name seen, even when its entry is
148		// invalid or a duplicate; usable holds only names with a valid, unique
149		// schema. Resources referencing a declared-but-unusable name are spared
150		// property-level errors.
151		declared := map[string]bool{}
152		usable := map[string]any{}
153		for i, entry := range typeEntries {
154			entryPath := fmt.Sprintf("/resourceTypes/%d", i)
155			obj, ok := entry.(map[string]any)
156			if !ok {
157				add(codeInvalidDocument, "resource type entry must be an object", entryPath)
158				continue
159			}
160			name, nameValid := identifierField(obj, "name", entryPath, add)
161			schemaRaw, hasSchema := obj["schema"]
162			schemaValid := false
163			if !hasSchema {
164				add(codeInvalidDocument, `missing required field "schema"`, entryPath)
165			} else {
166				before := len(errs)
167				validateSchema(schemaRaw, entryPath+"/schema", add)
168				schemaValid = len(errs) == before
169			}
170			if !nameValid {
171				continue
172			}
173			if declared[name] {
174				add(codeDuplicateIdentifier, fmt.Sprintf("duplicate resource type name %q", name), entryPath+"/name")
175				delete(usable, name)
176				continue
177			}
178			declared[name] = true
179			if schemaValid {
180				usable[name] = schemaRaw
181			}
182		}
183	
184		seenAddresses := map[string]bool{}
185		for i, entry := range resourceEntries {
186			entryPath := fmt.Sprintf("/resources/%d", i)
187			obj, ok := entry.(map[string]any)
188			if !ok {
189				add(codeInvalidDocument, "resource entry must be an object", entryPath)
190				continue
191			}
192			if address, ok := identifierField(obj, "address", entryPath, add); ok {
193				if seenAddresses[address] {
194					add(codeDuplicateIdentifier, fmt.Sprintf("duplicate resource address %q", address), entryPath+"/address")
195				} else {
196					seenAddresses[address] = true
197				}
198			}
199	
200			var schema any
201			schemaUsable := false
202			typeRaw, hasType := obj["type"]
203			typeName, typeIsString := typeRaw.(string)
204			switch {
205			case !hasType:
206				add(codeInvalidDocument, `missing required field "type"`, entryPath)
207			case !typeIsString:
208				add(codeInvalidDocument, `"type" must be a string`, entryPath+"/type")
209			case typeName == "":
210				add(codeInvalidDocument, `"type" must not be empty`, entryPath+"/type")
211			case !declared[typeName]:
212				add(codeUnknownResourceType, fmt.Sprintf("unknown resource type %q", typeName), entryPath+"/type")
213			default:
214				if s, ok := usable[typeName]; ok {
215					schema, schemaUsable = s, true
216				}
217			}
218	
219			propsRaw, hasProps := obj["properties"]
220			if !hasProps {
221				add(codeInvalidDocument, `missing required field "properties"`, entryPath)
222				continue
223			}
224			props, ok := propsRaw.(map[string]any)
225			if !ok {
226				add(codeInvalidDocument, `"properties" must be an object`, entryPath+"/properties")
227				continue
228			}
229			if schemaUsable {
230				validateValue(props, schema, entryPath+"/properties", add)
231			}
232		}
233	
234		return errs
235	}
236	
237	// identifierField extracts a required non-empty string field, reporting
238	// invalid_document for a missing, non-string, or empty value.
239	func identifierField(obj map[string]any, field, path string, add func(code, message, path string)) (string, bool) {
240		raw, ok := obj[field]
241		if !ok {
242			add(codeInvalidDocument, fmt.Sprintf("missing required field %q", field), path)
243			return "", false
244		}
245		s, ok := raw.(string)
246		if !ok {
247			add(codeInvalidDocument, fmt.Sprintf("%q must be a string", field), path+"/"+field)
248			return "", false
249		}
250		if s == "" {
251			add(codeInvalidDocument, fmt.Sprintf("%q must not be empty", field), path+"/"+field)
252			return "", false
253		}
254		return s, true
255	}
256	
257	// validateSchema checks the structural legality of a schema, recursing into
258	// array items and object properties.
259	func validateSchema(schema any, path string, add func(code, message, path string)) {
260		obj, ok := schema.(map[string]any)
261		if !ok {
262			add(codeInvalidDocument, "schema must be an object", path)
263			return
264		}
265		typeRaw, hasType := obj["type"]
266		typeName, isString := typeRaw.(string)
267		if !hasType {
268			add(codeInvalidDocument, `missing required field "type"`, path)
269			return
270		}
271		if !isString {
272			add(codeInvalidDocument, `"type" must be a string`, path+"/type")
273			return
274		}
275		switch typeName {
276		case "string", "integer", "number", "boolean":
277		case "array":
278			items, has := obj["items"]
279			if !has {
280				add(codeInvalidDocument, `array schema requires "items"`, path)
281				return
282			}
283			validateSchema(items, path+"/items", add)
284		case "object":
285			if propsRaw, has := obj["properties"]; has {
286				props, ok := propsRaw.(map[string]any)
287				if !ok {
288					add(codeInvalidDocument, `"properties" must be an object`, path+"/properties")
289				} else {
290					names := make([]string, 0, len(props))
291					for name := range props {
292						names = append(names, name)
293					}
294					sort.Strings(names)
295					for _, name := range names {
296						validateSchema(props[name], path+"/properties/"+pointerEscape(name), add)
297					}
298				}
299			}
300			if reqRaw, has := obj["required"]; has {
301				req, ok := reqRaw.([]any)
302				if !ok {
303					add(codeInvalidDocument, `"required" must be an array of strings`, path+"/required")
304				} else {
305					for j, entry := range req {
306						if _, ok := entry.(string); !ok {
307							add(codeInvalidDocument, `"required" entries must be strings`, fmt.Sprintf("%s/required/%d", path, j))
308						}
309					}
310				}
311			}
312			if apRaw, has := obj["additionalProperties"]; has {
313				if _, ok := apRaw.(bool); !ok {
314					add(codeInvalidDocument, `"additionalProperties" must be a boolean`, path+"/additionalProperties")
315				}
316			}
317		default:
318			add(codeInvalidDocument, fmt.Sprintf("unknown schema type %q", typeName), path+"/type")
319		}
320	}
321	
322	// validateValue checks a value against an already-validated schema.
323	func validateValue(value, schema any, path string, add func(code, message, path string)) {
324		obj, ok := schema.(map[string]any)
325		if !ok {
326			return
327		}
328		typeName, _ := obj["type"].(string)
329		switch typeName {
330		case "string":
331			if _, ok := value.(string); !ok {
332				add(codeTypeMismatch, fmt.Sprintf("expected string, got %s", jsonTypeName(value)), path)
333			}
334		case "boolean":
335			if _, ok := value.(bool); !ok {
336				add(codeTypeMismatch, fmt.Sprintf("expected boolean, got %s", jsonTypeName(value)), path)
337			}
338		case "integer":
339			n, ok := value.(json.Number)
340			if !ok || !isJSONInteger(n) {
341				add(codeTypeMismatch, fmt.Sprintf("expected integer, got %s", jsonTypeName(value)), path)
342			}
343		case "number":
344			if _, ok := value.(json.Number); !ok {
345				add(codeTypeMismatch, fmt.Sprintf("expected number, got %s", jsonTypeName(value)), path)
346			}
347		case "array":
348			arr, ok := value.([]any)
349			if !ok {
350				add(codeTypeMismatch, fmt.Sprintf("expected array, got %s", jsonTypeName(value)), path)
351				return
352			}
353			items := obj["items"]
354			for i, el := range arr {
355				validateValue(el, items, fmt.Sprintf("%s/%d", path, i), add)
356			}
357		case "object":
358			rec, ok := value.(map[string]any)
359			if !ok {
360				add(codeTypeMismatch, fmt.Sprintf("expected object, got %s", jsonTypeName(value)), path)
361				return
362			}
363			props, _ := obj["properties"].(map[string]any)
364			additional := false
365			if ap, ok := obj["additionalProperties"].(bool); ok {
366				additional = ap
367			}
368			seen := map[string]bool{}
369			if reqRaw, ok := obj["required"].([]any); ok {
370				for _, entry := range reqRaw {
371					name, ok := entry.(string)
372					if !ok || seen[name] {
373						continue
374					}
375					seen[name] = true
376					if _, present := rec[name]; !present {
377						add(codeMissingRequiredProperty, fmt.Sprintf("missing required property %q", name), path)
378					}
379				}
380			}
381			names := make([]string, 0, len(rec))
382			for name := range rec {
383				names = append(names, name)
384			}
385			sort.Strings(names)
386			for _, name := range names {
387				childPath := path + "/" + pointerEscape(name)
388				if sub, declared := props[name]; declared {
389					validateValue(rec[name], sub, childPath, add)
390				} else if !additional {
391					add(codeUnexpectedProperty, fmt.Sprintf("unexpected property %q", name), childPath)
392				}
393			}
394		}
395	}
396	
397	// isJSONInteger reports whether a JSON number literal denotes an integer.
398	// Whole-valued forms such as 1.0 or 1e2 count as integers; fractions do not.
399	func isJSONInteger(n json.Number) bool {
400		s := n.String()
401		if _, err := strconv.ParseInt(s, 10, 64); err == nil {
402			return true
403		}
404		f, err := strconv.ParseFloat(s, 64)
405		if err != nil {
406			return false
407		}
408		return !math.IsInf(f, 0) && f == math.Trunc(f)
409	}
410	
411	func jsonTypeName(v any) string {
412		switch v.(type) {
413		case nil:
414			return "null"
415		case bool:
416			return "boolean"
417		case json.Number:
418			return "number"
419		case string:
420			return "string"
421		case []any:
422			return "array"
423		case map[string]any:
424			return "object"
425		default:
426			return "value"
427		}
428	}
